  "e-reporting/ereporting.xsd": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\"\r\nxmlns:rep=\"report\"\r\nxmlns:trs=\"transaction\"\r\nxmlns:pay=\"payment\">\r\n\r\n    <xs:import namespace=\"report\" schemaLocation=\"report.xsd\"/>\r\n    <xs:import namespace=\"transaction\" schemaLocation=\"transaction.xsd\"/>\r\n    <xs:import namespace=\"payment\" schemaLocation=\"payment.xsd\"/>\r\n\r\n    <xs:element name=\"Report\" type=\"ReportType\">\r\n        <xs:annotation>\r\n            <xs:documentation>TB-0 : Rapport</xs:documentation>\r\n        </xs:annotation>\r\n    </xs:element>\r\n\r\n    <xs:complexType name=\"ReportType\">\r\n        <xs:sequence>\r\n            <xs:element name=\"ReportDocument\" type=\"rep:ReportDocumentType\" minOccurs=\"1\" maxOccurs=\"1\">\r\n                <xs:annotation>\r\n                    <xs:documentation>TB-1 : Flux 10 racine</xs:documentation>\r\n                </xs:annotation>\r\n            </xs:element>\r\n            <xs:element name=\"TransactionsReport\" type=\"trs:TransactionsReportType\" minOccurs=\"0\" maxOccurs=\"1\">\r\n                <xs:annotation>\r\n                    <xs:documentation>TB-2 : Transmission des transactions flux 10.1 et 10.3</xs:documentation>\r\n                </xs:annotation>\r\n            </xs:element>\r\n            <xs:element name=\"PaymentsReport\" type=\"pay:PaymentsReportType\" minOccurs=\"0\" maxOccurs=\"1\">\r\n                <xs:annotation>\r\n                    <xs:documentation>TB-3 : Transmission des paiements flux 10.2 et 10.4</xs:documentation>\r\n                </xs:annotation>\r\n            </xs:element>\r\n        </xs:sequence>\r\n    </xs:complexType>\r\n\r\n</xs:schema>",
